import "./steps.css";

export interface StepItem {
  title: string;
  body: string;
}
export interface StepsProps {
  eyebrow: string;
  heading: string;
  items: StepItem[];
  tone: "white" | "light" | "dark";
}

export function StepsRender({ eyebrow, heading, items, tone }: StepsProps) {
  const list = items || [];
  const cols = Math.min(4, Math.max(1, list.length));
  return (
    <div className="p1-steps p1-block" data-tone={tone}>
      <div className="p1-steps__inner">
        <div className="p1-steps__header">
          {eyebrow && <p className="p1-steps__eyebrow">{eyebrow}</p>}
          {heading && <h2 className="p1-steps__heading">{heading}</h2>}
        </div>
        <div
          className="p1-steps__grid"
          style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
        >
          {list.map((it, i) => (
            <div key={i} className="p1-steps__item">
              <div className="p1-steps__number" aria-hidden="true">{i + 1}</div>
              <h3 className="p1-steps__item-title">{it.title}</h3>
              <p className="p1-steps__item-body">{it.body}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { StepsRender, type StepsProps, type StepItem } from "./steps";
export type { StepsProps, StepItem };

export const StepsBlock: ComponentConfig<StepsProps> = {
  fields: {
    eyebrow: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label above the heading. 2–4 words. E.g. How it works." },
    },
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Section heading. Short and directive, under 8 words." },
    },
    items: {
      type: "array" as const,
      arrayFields: {
        title: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Step name. 1–3 words, verb or noun." },
        },
        body: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "1–2 sentence description of this step." },
        },
      },
      defaultItemProps: { title: "Step", body: "Describe this step." },
      getItemSummary: (item: StepItem) => item.title || "Step",
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "White", value: "white" },
        { label: "Light", value: "light" },
        { label: "Dark", value: "dark" },
      ],
    },
  },
  defaultProps: {
    eyebrow: "How it works",
    heading: "Ship in three steps.",
    items: [
      { title: "Plan", body: "Start from a template or a blank page and outline what you want to say." },
      { title: "Build", body: "Compose your page from ready-made blocks — no code required." },
      { title: "Publish", body: "Preview your changes, then make them live in a single click." },
    ],
    tone: "light",
  },
  render: StepsRender,
};

export const meta = defineMeta({
  title: 'Steps',
  description: 'Numbered sequential steps with eyebrow, heading, and title+body per step in a 1–4 column layout; use for how-it-works or onboarding flows.',
  categories: ["value"],
  published: true,
});

.p1-steps[data-tone="light"] { background-color: var(--p1-surface-subtle); }
.p1-steps[data-tone="dark"] {
  background-color: var(--p1-surface-inverse);
  color: var(--p1-fg-inverse);
}

.p1-steps__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-steps__header {
  margin-block-end: var(--p1-space-xl);
  text-align: center;
}
.p1-steps__eyebrow {
  color: var(--p1-accent);
  font-size: var(--p1-text-lg);
  font-style: italic;
  margin-block-end: var(--p1-space-xs);
}
.p1-steps[data-tone="dark"] .p1-steps__eyebrow { color: var(--p1-warning); }

.p1-steps__heading {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-steps__heading { font-size: var(--p1-text-3xl); }
}

.p1-steps__grid {
  display: grid;
  gap: var(--p1-space-xl);
  grid-template-columns: 1fr;
}
@media (width >= 40rem) {
  .p1-steps__grid { grid-template-columns: repeat(2, 1fr); }
}
@media (width < 40rem) {
  .p1-steps__grid { grid-template-columns: 1fr !important; }
}

.p1-steps__item { display: flex; flex-direction: column; gap: var(--p1-space-sm); }

.p1-steps__number {
  align-items: center;
  background-color: color-mix(in oklch, var(--p1-accent) 8%, transparent);
  block-size: 3rem;
  border-radius: var(--p1-radius-pill);
  color: var(--p1-accent);
  display: grid;
  font-size: var(--p1-text-lg);
  font-weight: 800;
  inline-size: 3rem;
  justify-items: center;
  place-content: center;
}
.p1-steps[data-tone="dark"] .p1-steps__number {
  background-color: color-mix(in oklch, var(--p1-warning) 15%, transparent);
  color: var(--p1-warning);
}

.p1-steps__item-title {
  font-size: var(--p1-text-xl);
  font-weight: var(--p1-weight-bold);
  margin-block-start: var(--p1-space-xs);
}
.p1-steps__item-body {
  color: var(--p1-fg-muted);
  font-size: 0.9375rem;
  line-height: var(--p1-leading-normal);
}
.p1-steps[data-tone="dark"] .p1-steps__item-body { color: var(--p1-fg-inverse-subtle); }

